    "description": "내셔널 지오그래픽 얼티밋 익스플로러는 갤러리아 몰에 위치한 가족 친화적 인터랙티브 체험 공간으로, 내셔널 지오그래픽의 세계를 직접 탐험할 수 있습니다. 디지털 기술을 활용한 인터랙티브 전시에서 정글 탐험, 해양 다이빙, 우주 여행 등을 가상으로 체험하며 과학과 자연에 대해 배웁니다. 아이들이 탐험가가 되어 미션을 수행하는 형식으로 진행되어 교육적이면서도 재미있습니다. VR 체험, 클라이밍 월, 슬라이드 등 다양한 액티비티가 있어 반나절 정도 즐기기에 적합합니다. 더운 날씨에 에어컨이 잘 되는 실내에서 아이들과 유익한 시간을 보내기 완벽한 장소입니다.",
